	 _enforceLobbySafety(room){if(!room||room.phase!=="lobby"||room._safetySeparationActive)return false;const ids=[...room.members];for(let leftIndex=0;leftIndex<ids.length;leftIndex++)for(let rightIndex=leftIndex+1;rightIndex<ids.length;rightIndex++){const leftId=ids[leftIndex],rightId=ids[rightIndex];if(!this.friends.interactionBlocked(leftId,rightId))continue;let leavingId;if(room.leaderId===leftId)leavingId=rightId;else if(room.leaderId===rightId)leavingId=leftId;else leavingId=this.friends.hasBlocked(leftId,rightId)?leftId:rightId;const leaving=this.sessions.get(leavingId);if(leaving){room._safetySeparationActive=true;try{this.leaveRoom(leaving)}finally{delete room._safetySeparationActive}return true}}return false}
